import React, { useState, useEffect, useRef } from 'react';
import './AvatarPicker.css';

const isImageFile = (file) => file && file.type.startsWith('image/');

const fileToDataUrl = (file) =>
  new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(new Error('Failed to read image file'));
    reader.readAsDataURL(file);
  });

export default function AvatarPicker({ avatarUrl, scale = 1, offsetX = 0, offsetY = 0, onSave, onDelete }) {
  const [showModal, setShowModal] = useState(false);
  const [selectedFile, setSelectedFile] = useState(null);
  const [previewUrl, setPreviewUrl] = useState(avatarUrl || null);
  const [previewScale, setPreviewScale] = useState(scale);
  const [previewOffsetX, setPreviewOffsetX] = useState(offsetX);
  const [previewOffsetY, setPreviewOffsetY] = useState(offsetY);
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const previewCircleRef = useRef(null);
  const backdropRef = useRef();

  useEffect(() => {
    setPreviewUrl(avatarUrl || null);
    setPreviewScale(scale);
    setPreviewOffsetX(offsetX);
    setPreviewOffsetY(offsetY);
  }, [avatarUrl, scale, offsetX, offsetY]);

  useEffect(() => {
    return () => {
      if (selectedFile && previewUrl && previewUrl.startsWith('blob:')) {
        URL.revokeObjectURL(previewUrl);
      }
    };
  }, [selectedFile, previewUrl]);

  const openModal = () => {
    setShowModal(true);
    setSelectedFile(null);
    setPreviewUrl(avatarUrl || null);
    setPreviewScale(scale);
    setPreviewOffsetX(offsetX);
    setPreviewOffsetY(offsetY);
  };

  const closeModal = () => {
    setShowModal(false);
  };

  const handleFileChange = (event) => {
    const file = event.target.files[0];
    if (!file) {
      setSelectedFile(null);
      setPreviewUrl(avatarUrl || null);
      return;
    }

    if (!isImageFile(file)) {
      alert('Please choose an image file for your profile picture.');
      return;
    }

    const objectUrl = URL.createObjectURL(file);
    setSelectedFile(file);
    setPreviewUrl(objectUrl);
    setPreviewScale(1);
    setPreviewOffsetX(0);
    setPreviewOffsetY(0);
  };

  const handleDragStart = (e) => {
    setIsDragging(true);
    setDragStart({ x: e.clientX, y: e.clientY });
  };

  const handleDragMove = (e) => {
    if (!isDragging) return;
    const deltaX = e.clientX - dragStart.x;
    const deltaY = e.clientY - dragStart.y;
    setPreviewOffsetX((prev) => prev + deltaX);
    setPreviewOffsetY((prev) => prev + deltaY);
    setDragStart({ x: e.clientX, y: e.clientY });
  };

  const handleDragEnd = () => {
    setIsDragging(false);
  };

  useEffect(() => {
    if (isDragging) {
      document.addEventListener('mousemove', handleDragMove);
      document.addEventListener('mouseup', handleDragEnd);
      return () => {
        document.removeEventListener('mousemove', handleDragMove);
        document.removeEventListener('mouseup', handleDragEnd);
      };
    }
  }, [isDragging, dragStart]);

  const handleSave = async () => {
    if (!selectedFile && !avatarUrl) {
      alert('Please select an image to save.');
      return;
    }

    if (selectedFile) {
      try {
        const dataUrl = await fileToDataUrl(selectedFile);
        onSave(dataUrl, previewScale, previewOffsetX, previewOffsetY);
      } catch (error) {
        console.error(error);
        alert('Unable to load the selected image. Please choose a different file.');
        return;
      }
    } else {
      onSave(avatarUrl, previewScale, previewOffsetX, previewOffsetY);
    }

    closeModal();
  };

  const handleDelete = () => {
    onDelete();
    closeModal();
  };

  const stopPropagation = (event) => {
    event.stopPropagation();
  };

  return (
    <>
      <button type="button" className="avatar-picker-button" onClick={openModal}>
        <div className="avatar-picker-circle">
          {avatarUrl ? (
            <img
              src={avatarUrl}
              alt="Profile avatar"
              style={{ transform: `scale(${scale})` }}
            />
          ) : (
            <span>Upload</span>
          )}
        </div>
      </button>

      {showModal && (
        <div className="avatar-picker-backdrop" onClick={closeModal} ref={backdropRef}>
          <div className="avatar-picker-modal" onClick={stopPropagation}>
            <div className="avatar-picker-header">
              <h2>Edit profile picture</h2>
              <p className="avatar-picker-subtitle">Upload a new image, resize and drag it to position within the circle.</p>
            </div>

            <div className="avatar-picker-preview-row">
              <div
                className="avatar-picker-preview-circle"
                ref={previewCircleRef}
                onMouseDown={handleDragStart}
              >
                {previewUrl ? (
                  <img
                    src={previewUrl}
                    alt="Preview avatar"
                    style={{
                      transform: `scale(${previewScale}) translate(${previewOffsetX}px, ${previewOffsetY}px)`,
                      cursor: isDragging ? 'grabbing' : 'grab'
                    }}
                  />
                ) : (
                  <span>No image selected</span>
                )}
              </div>
              <div className="avatar-picker-controls">
                <label className="avatar-picker-file-label">
                  Choose image
                  <input type="file" accept="image/*" onChange={handleFileChange} />
                </label>
                <div className="avatar-picker-zoom-row">
                  <label htmlFor="avatar-zoom">Resize</label>
                  <input
                    id="avatar-zoom"
                    type="range"
                    min="1"
                    max="2"
                    step="0.01"
                    value={previewScale}
                    onChange={(e) => setPreviewScale(Number(e.target.value))}
                  />
                  <span>{Math.round(previewScale * 100)}%</span>
                </div>
                <div className="avatar-picker-actions">
                  <button type="button" className="button-primary" onClick={handleSave}>
                    Save
                  </button>
                  <button type="button" className="button-secondary" onClick={closeModal}>
                    Cancel
                  </button>
                </div>
                {avatarUrl && (
                  <button type="button" className="button-danger" onClick={handleDelete}>
                    Delete profile picture
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
}
